// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/approvals/{requestId}", wrapper.GetApproval)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/approvals/{requestId}/holds", wrapper.AuthorisePayout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/approvals/{requestId}/rejections", wrapper.RejectApproval)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/approvals/{requestId}/signatures", wrapper.SignApproval)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/codes/verify", wrapper.PostVerifyCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/pin-proofs", wrapper.PostPinProof)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/sign-in", wrapper.PostSignIn)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/sign-out", wrapper.PostSignOut)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealthz)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/holds/{holdId}/releases", wrapper.ReleaseHold)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/loans/{loanId}", wrapper.GetLoan)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/members/{memberId}/loans", wrapper.GetMemberLoans)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/members/{memberId}/statement", wrapper.GetMemberStatement)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/members/{memberId}/withdrawal-requests", wrapper.GetMemberWithdrawalRequests)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/societies/{societyId}/accounts", wrapper.GetChartOfAccounts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/societies/{societyId}/accounts/{accountCode}/ledger", wrapper.GetGeneralLedger)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/societies/{societyId}/approval-requests", wrapper.GetSocietyApprovalRequests)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/societies/{societyId}/contributions", wrapper.RecordContribution)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/societies/{societyId}/journal", wrapper.GetJournal)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/societies/{societyId}/ledger/batches", wrapper.PostLedgerBatch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/societies/{societyId}/loans", wrapper.GetSocietyLoans)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/societies/{societyId}/payouts", wrapper.RecordPayout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/societies/{societyId}/trial-balance", wrapper.GetTrialBalance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/societies/{societyId}/withdrawal-requests", wrapper.RaiseWithdrawalRequest)
	})

	return r
}

